 15	/// Safe replacement for the former void-pointer synchronous callback table.
 16	pub trait ProtocolBackend {
 17	    fn call_tool(&mut self, request: &JsonDocument<'_>, arguments: usize, name: &str) -> Option<ToolResponse>;
 18	    fn read_resource(&mut self, _request: &JsonDocument<'_>, _uri: &str) -> Option<Vec<u8>> { None }
 19	}
