 21	/// Safe replacement for the former void-pointer opt-in async backend.
 22	pub trait AsyncBackend {
 23	    fn tasks_available(&self) -> bool;
 24	    fn call_tool(&mut self, request: &JsonDocument<'_>, arguments: usize, name: &str, modern: bool, supports_tasks: bool) -> (AsyncDisposition, Vec<u8>);
 25	    fn get_task(&mut self, request: &JsonDocument<'_>, task_id: &str) -> (AsyncDisposition, Vec<u8>);
 26	    fn cancel_task(&mut self, request: &JsonDocument<'_>, task_id: &str) -> (AsyncDisposition, Vec<u8>);
 27	    fn cancel_request(&mut self, _request: &JsonDocument<'_>, _request_id: usize) {}
 28	}
