  5	const LEGACY: &[u8] = b"2025-11-25";
  6	const CURRENT: &[u8] = b"2026-07-28";
  7	const LIMIT: usize = MAX_BYTES;
  8	
  9	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 10	enum ProtocolVersion { Legacy, Current }
