 12	#[derive(Debug, Default)]
 13	pub struct ProtocolSession {
 14	    pub initialized: bool,
 15	    pub modern: bool,
 16	    protocol_version: Option<ProtocolVersion>,
 17	    window_started: Option<Instant>,
 18	    requests_in_window: u32,
 19	}
 20	impl ProtocolSession {
 21	    pub fn reset(&mut self) { *self=Self::default(); }
 22	    pub fn protocol_version(&self) -> Option<&'static str> { match self.protocol_version { Some(ProtocolVersion::Legacy)=>Some("2025-11-25"),Some(ProtocolVersion::Current)=>Some("2026-07-28"),None=>None } }
 23	}
