 32	pub fn handle<B:ProtocolBackend+?Sized>(session:&mut ProtocolSession,line:&[u8],backend:Option<&mut B>)->Result<Vec<u8>,ProtocolError>{handle_async::<B,NoAsync>(session,line,backend,None)}
 33	
 34	pub fn handle_async<B:ProtocolBackend+?Sized,A:AsyncBackend+?Sized>(session:&mut ProtocolSession,line:&[u8],mut backend:Option<&mut B>,mut async_backend:Option<&mut A>)->Result<Vec<u8>,ProtocolError>{
 35	    if line.is_empty()||line.len()>LIMIT{return Err(ProtocolError::InvalidInput);}
 36	    let mut out=buffer()?;
 37	    let doc=match JsonDocument::parse(line){Ok(v)=>v,Err(_)=>{append_error(&mut out,None,-32700,"parse error",None)?;return bytes(out);}};
 38	    let root=doc.root();
 39	    if doc.token(root).is_none_or(|t|t.kind!=JsonType::Object){append_error(&mut out,None,-32600,"invalid request",None)?;return bytes(out);}
 40	    let id=doc.object_get(root,b"id"); let method_token=doc.object_get(root,b"method");
 41	    let valid_id=id.is_none_or(|v|doc.token(v).is_some_and(|t|matches!(t.kind,JsonType::String|JsonType::Number)));
 42	    let Some(method_token)=method_token.filter(|v|doc.token(*v).is_some_and(|t|t.kind==JsonType::String)) else {
 43	        if let Some(id)=id { if valid_id {append_error(&mut out,Some(doc.raw_token(id).unwrap_or(b"null")),-32600,"invalid request",None)?;} }
 44	        return bytes(out);
 45	    };
 46	    if !doc.string_equals(doc.object_get(root,b"jsonrpc").unwrap_or(usize::MAX),b"2.0")||!valid_id {
 47	        if let Some(id)=id.filter(|_|valid_id){append_error(&mut out,Some(doc.raw_token(id).unwrap_or(b"null")),-32600,"invalid request",None)?;}
 48	        return bytes(out);
 49	    }
 50	    let method_bytes=doc.decoded_string(method_token).ok_or(ProtocolError::InvalidInput)?;
 51	    let method=std::str::from_utf8(&method_bytes).unwrap_or("");
 52	    let has_id=id.is_some();
 53	    if !has_id&&!method.starts_with("notifications/"){return Ok(Vec::new());}
 54	    rate_check(session,has_id,id.and_then(|i|doc.raw_token(i)),&mut out)?;
 55	    if !out.is_empty(){return bytes(out);}
 56	    let params=doc.object_get(root,b"params");
 57	    let modern_probe=method=="server/discover";
 58	    let modern_request=request_is_modern(&doc,params);
 59	    if modern_probe {
 60	        if has_id { if valid_modern_envelope(&doc,params) {append_discover(session,&doc,id.unwrap(),async_backend.as_deref().is_some_and(|b|b.tasks_available()),&mut out)?;} else {append_error(&mut out,id.and_then(|i|doc.raw_token(i)),-32022,"server/discover requires current protocol version metadata",Some(r#"{"supported":["2026-07-28"]}"#))?;} }
 61	        return bytes(out);
 62	    }
 63	    if session.modern||modern_request {
 64	        if !valid_modern_envelope(&doc,params) { if has_id {append_error(&mut out,id.and_then(|i|doc.raw_token(i)),-32022,"unsupported or missing protocol version metadata",Some(r#"{"supported":["2026-07-28"]}"#))?;} return bytes(out); }
 65	        session.modern=true; session.protocol_version=Some(ProtocolVersion::Current);
 66	    } else if method!="initialize"&&method!="notifications/initialized"&&!session.initialized&&method!="ping" {
 67	        if has_id {append_error(&mut out,id.and_then(|i|doc.raw_token(i)),-32002,"initialize must complete before requests",None)?;} return bytes(out);
 68	    }
 69	    if method=="initialize" { if has_id {append_initialize(session,&doc,params,id.unwrap(),&mut out)?;} }
 70	    else if method=="notifications/initialized" {session.initialized=true;}
 71	    else if method=="notifications/cancelled" {
 72	        if !has_id&&session.initialized&&!session.modern { if let (Some(a),Some(p))=(async_backend.as_deref_mut(),params) { if doc.token(p).is_some_and(|t|t.kind==JsonType::Object) { if let Some(req)=doc.object_get(p,b"requestId").filter(|v|doc.token(*v).is_some_and(|t|matches!(t.kind,JsonType::String|JsonType::Number))){a.cancel_request(&doc,req);} } } }
 73	    }
 74	    else if method=="notifications/progress" {}
 75	    else if method=="ping" {if has_id {response_prefix(&mut out,&doc,id.unwrap())?;response_suffix(&mut out,session.modern)?;}}
 76	    else if method=="tools/list" {if has_id {response_prefix(&mut out,&doc,id.unwrap())?;lit(&mut out,"\"tools\":")?;out.append(&crate::tool_schemas()?).map_err(ProtocolError::Buffer)?;response_suffix(&mut out,session.modern)?;}}
 77	    else if method=="tools/call" {if has_id {append_tool_call(session,&doc,params,id.unwrap(),backend.as_deref_mut(),async_backend.as_deref_mut(),&mut out)?;}}
 78	    else if method=="tasks/get"||method=="tasks/cancel" {if has_id {append_task_method(session.modern,&doc,params,id.unwrap(),method,async_backend.as_deref_mut(),&mut out)?;}}
 79	    else if method=="resources/list" {if has_id {response_prefix(&mut out,&doc,id.unwrap())?;lit(&mut out,r#""resources":[{"uri":"vexel://documents/current/source","name":"Current SVG source","description":"Source-preserving SVG text for the current document.","mimeType":"image/svg+xml"},{"uri":"vexel://documents/current/tree","name":"Current SVG tree","description":"Bounded element-tree summary for the current document.","mimeType":"application/json"},{"uri":"vexel://documents/current/render","name":"Last document render","description":"Last bounded PNG render.","mimeType":"image/png"}]"#)?;response_suffix(&mut out,session.modern)?;}}
 80	    else if method=="resources/read" {if has_id {append_resource_read(session,&doc,params,id.unwrap(),backend.as_deref_mut(),&mut out)?;}}
 81	    else if method=="prompts/list" {if has_id {response_prefix(&mut out,&doc,id.unwrap())?;lit(&mut out,r#""prompts":[{"name":"inspect-document","description":"Inspect the open SVG structure and identify unsupported content.","arguments":[]}]"#)?;response_suffix(&mut out,session.modern)?;}}
 82	    else if method=="prompts/get" {if has_id {response_prefix(&mut out,&doc,id.unwrap())?;if params.and_then(|p|doc.object_get(p,b"name")).is_some_and(|v|doc.string_equals(v,b"inspect-document")){lit(&mut out,r#""description":"Inspect the open SVG document.","messages":[{"role":"user","content":{"type":"text","text":"Use document_list and document_info, then inspect a bounded tree page. Report unsupported features before suggesting edits."}}]"#)?;}else{lit(&mut out,"\"messages\":[]")?;}response_suffix(&mut out,session.modern)?;}}
 83	    else if has_id {append_error(&mut out,id.and_then(|i|doc.raw_token(i)),-32601,"method not found",None)?;}
 84	    bytes(out)
 85	}
