 87	fn buffer()->Result<JsonBuffer,ProtocolError>{JsonBuffer::new(256,LIMIT).map_err(ProtocolError::Buffer)}
 88	fn bytes(b:JsonBuffer)->Result<Vec<u8>,ProtocolError>{let mut result=Vec::new();result.try_reserve_exact(b.len()).map_err(|_|ProtocolError::Allocation)?;result.extend_from_slice(b.as_bytes());Ok(result)}
 89	fn lit(out:&mut JsonBuffer,s:&str)->Result<(),ProtocolError>{out.literal(s).map_err(ProtocolError::Buffer)}
 90	fn rate_check(session:&mut ProtocolSession,has_id:bool,id:Option<&[u8]>,out:&mut JsonBuffer)->Result<(),ProtocolError>{
 91	    let now=Instant::now(); if session.window_started.is_none_or(|start|now.duration_since(start).as_millis()>=60_000){session.window_started=Some(now);session.requests_in_window=0;}
 92	    session.requests_in_window=session.requests_in_window.saturating_add(1);
 93	    if session.requests_in_window>120&&has_id{append_error(out,id,-32000,"rate limit exceeded",None)?;} Ok(())
 94	}
 95	fn append_error(out:&mut JsonBuffer,id:Option<&[u8]>,code:i32,message:&str,data:Option<&str>)->Result<(),ProtocolError>{
 96	    lit(out,"{\"jsonrpc\":\"2.0\",\"id\":")?;out.append(id.unwrap_or(b"null")).map_err(ProtocolError::Buffer)?;
 97	    lit(out,",\"error\":{\"code\":")?;append_i32(out,code)?;lit(out,",\"message\":")?;append_string(out,message.as_bytes())?;
 98	    if let Some(data)=data{lit(out,",\"data\":")?;lit(out,data)?;}lit(out,"}}")
 99	}
100	fn append_i32(out:&mut JsonBuffer,value:i32)->Result<(),ProtocolError>{
101	    let mut digits=[0u8;10];let mut n=value.unsigned_abs();let mut at=digits.len();
102	    loop{at-=1;digits[at]=b'0'+(n%10) as u8;n/=10;if n==0{break;}}
103	    if value<0{out.append(b"-").map_err(ProtocolError::Buffer)?;}out.append(&digits[at..]).map_err(ProtocolError::Buffer)
104	}
105	fn response_prefix(out:&mut JsonBuffer,doc:&JsonDocument<'_>,id:usize)->Result<(),ProtocolError>{lit(out,"{\"jsonrpc\":\"2.0\",\"id\":")?;append_raw(out,doc,id)?;lit(out,",\"result\":{")}
106	fn response_suffix(out:&mut JsonBuffer,modern:bool)->Result<(),ProtocolError>{
107	    if modern {let comma=!(out.as_bytes().last()==Some(&b'{')); if comma{lit(out,",")?;}lit(out,r#""_meta":{"io.modelcontextprotocol/serverInfo":{"name":"Vexel","version":"0.1.0"}}"#)?;}lit(out,"}}")
108	}
109	fn request_is_modern(doc:&JsonDocument<'_>,params:Option<usize>)->bool{params.and_then(|p|doc.object_get(p,b"_meta")).and_then(|m|doc.object_get(m,b"io.modelcontextprotocol/protocolVersion")).is_some_and(|v|doc.string_equals(v,CURRENT))}
110	fn valid_modern_envelope(doc:&JsonDocument<'_>,params:Option<usize>)->bool{request_is_modern(doc,params)}
111	fn append_capabilities(out:&mut JsonBuffer,tasks:bool)->Result<(),ProtocolError>{lit(out,"\"capabilities\":{")?;if tasks{lit(out,r#""io.modelcontextprotocol/tasks":{},"#)?;}lit(out,r#""tools":{"listChanged":false},"resources":{"subscribe":false,"listChanged":false},"prompts":{"listChanged":false}},"#)}
112	fn append_initialize(session:&mut ProtocolSession,doc:&JsonDocument<'_>,params:Option<usize>,id:usize,out:&mut JsonBuffer)->Result<(),ProtocolError>{
113	    if session.initialized||session.modern{return append_error(out,doc.raw_token(id),-32600,"initialize is not valid in this protocol session",None);}
114	    let version=params.and_then(|p|doc.object_get(p,b"protocolVersion"));if !version.is_some_and(|v|doc.string_equals(v,LEGACY)){return append_error(out,doc.raw_token(id),-32004,"unsupported protocol version",Some(r#"{"supported":["2025-11-25"]}"#));}
115	    session.protocol_version=Some(ProtocolVersion::Legacy);response_prefix(out,doc,id)?;lit(out,r#""protocolVersion":"2025-11-25","#)?;append_capabilities(out,false)?;lit(out,r#""serverInfo":{"name":"Vexel","version":"0.1.0"},"instructions":"Vexel MCP controls documents open in the Vexel app. File opens and Save As are restricted to user-granted directories."}}"#)
116	}
117	fn append_discover(session:&mut ProtocolSession,doc:&JsonDocument<'_>,id:usize,tasks:bool,out:&mut JsonBuffer)->Result<(),ProtocolError>{
118	    session.modern=true;session.protocol_version=Some(ProtocolVersion::Current);response_prefix(out,doc,id)?;lit(out,r#""supportedVersions":["2026-07-28"],"#)?;append_capabilities(out,tasks)?;lit(out,r#""instructions":"Vexel MCP controls documents open in the Vexel app. File opens and Save As are restricted to user-granted directories.","ttlMs":10000,"cacheScope":"connection""#)?;response_suffix(out,true)
119	}
