121	fn append_tool_call<B:ProtocolBackend+?Sized,A:AsyncBackend+?Sized>(session:&mut ProtocolSession,doc:&JsonDocument<'_>,params:Option<usize>,id:usize,mut backend:Option<&mut B>,mut async_backend:Option<&mut A>,out:&mut JsonBuffer)->Result<(),ProtocolError>{
122	    let name_token=params.and_then(|p|doc.object_get(p,b"name"));let args=params.and_then(|p|doc.object_get(p,b"arguments"));
123	    let name=name_token.and_then(|v|doc.decoded_string(v)).and_then(|v|String::from_utf8(v).ok());
124	    let (Some(name),Some(args))=(name,args) else{return append_error(out,doc.raw_token(id),-32602,"tools/call requires a tool name and arguments",None)};
125	    if name.is_empty()||name.len()>63||name.contains('\0'){return append_error(out,doc.raw_token(id),-32602,"tools/call requires a tool name and arguments",None)}
126	    if let Err(error)=validate_tool_arguments(doc,args,&name){let (msg,code)=match error{crate::ToolValidationError::UnknownTool=>("unknown tool","unknown_tool"),crate::ToolValidationError::UnexpectedArgument=>("unexpected argument","invalid_arguments"),crate::ToolValidationError::WrongType=>("argument has the wrong type","invalid_arguments"),crate::ToolValidationError::MissingRequired=>("required argument missing","invalid_arguments"),crate::ToolValidationError::InvalidLoopMode=>("mode is not a supported native loop value","invalid_arguments"),crate::ToolValidationError::InvalidTemplateAttributes=>("template attributes must map strings to strings","invalid_arguments"),crate::ToolValidationError::InvalidTransactionLength=>("transaction must contain between 1 and 64 edits","invalid_arguments"),crate::ToolValidationError::InvalidArguments=>("invalid tool arguments","invalid_arguments")};return append_tool_error(out,doc,id,session.modern,msg,code);}
127	    if let Some(a)=async_backend.as_deref_mut(){let ready=a.tasks_available();let supports=session.modern&&request_supports_tasks(doc,params)&&ready;let (disposition,payload)=a.call_tool(doc,args,&name,session.modern,supports);if disposition!=AsyncDisposition::Unhandled{return async_callback_response(doc,id,session.modern,supports,ready,AsyncPayloadKind::ToolResult,disposition,&payload,out);}}
128	    let Some(b)=backend.as_deref_mut() else{return append_tool_error(out,doc,id,session.modern,"Vexel broker is unavailable","broker_unavailable")};
129	    let Some(result)=b.call_tool(doc,args,&name) else{return append_tool_error(out,doc,id,session.modern,"The tool could not complete its request","tool_failed")};
130	    if result.structured_json.is_empty(){return append_tool_error(out,doc,id,session.modern,"The tool could not complete its request","tool_failed");}
131	    response_prefix(out,doc,id)?;lit(out,"\"content\":")?;
132	    if result.content_json.is_empty(){append_string(out,if result.is_error{b"Tool request failed"}else{b"Tool completed."})?;}else{out.append(&result.content_json).map_err(ProtocolError::Buffer)?;}
133	    lit(out,",\"structuredContent\":")?;out.append(&result.structured_json).map_err(ProtocolError::Buffer)?;lit(out,if result.is_error{",\"isError\":true"}else{",\"isError\":false"})?;response_suffix(out,session.modern)
134	}
135	fn append_tool_error(out:&mut JsonBuffer,doc:&JsonDocument<'_>,id:usize,modern:bool,message:&str,code:&str)->Result<(),ProtocolError>{response_prefix(out,doc,id)?;lit(out,"\"content\":[{\"type\":\"text\",\"text\":")?;append_string(out,message.as_bytes())?;lit(out,"}],\"structuredContent\":{\"error\":{\"code\":")?;append_string(out,code.as_bytes())?;lit(out,",\"message\":")?;append_string(out,message.as_bytes())?;lit(out,"}},\"isError\":true")?;response_suffix(out,modern)}
136	fn request_supports_tasks(doc:&JsonDocument<'_>,params:Option<usize>)->bool{params.and_then(|p|doc.object_get(p,b"_meta")).and_then(|m|doc.object_get(m,b"io.modelcontextprotocol/clientCapabilities")).and_then(|c|doc.object_get(c,b"extensions")).and_then(|e|doc.object_get(e,b"io.modelcontextprotocol/tasks")).is_some_and(|t|doc.token(t).is_some_and(|v|v.kind==JsonType::Object))}
137	
138	fn async_callback_response(doc:&JsonDocument<'_>,id:usize,modern:bool,supports:bool,ready:bool,kind:AsyncPayloadKind,disposition:AsyncDisposition,payload:&[u8],out:&mut JsonBuffer)->Result<(),ProtocolError>{
139	    if disposition==AsyncDisposition::Deferred {if modern{return append_error(out,doc.raw_token(id),-32603,"deferred response is unavailable for the current protocol",None)}return Ok(());}
140	    if disposition==AsyncDisposition::Failed{return append_error(out,doc.raw_token(id),-32603,"asynchronous protocol operation failed",None)}
141	    if !matches!(disposition,AsyncDisposition::Result|AsyncDisposition::Error){return append_error(out,doc.raw_token(id),-32603,"invalid asynchronous protocol disposition",None)}
142	    let is_error=disposition==AsyncDisposition::Error;let validation_kind=if is_error{AsyncPayloadKind::Error}else{kind};
143	    let is_task=match validate_async_payload(payload,validation_kind){Ok(v)=>v,Err(())=>return append_error(out,doc.raw_token(id),-32603,"asynchronous backend returned invalid JSON",None)};
144	    let overhead=512usize.checked_add(doc.raw_token(id).map_or(0,|v|v.len())).ok_or(ProtocolError::InvalidInput)?;
145	    if overhead>=LIMIT||payload.len()>LIMIT-overhead{return append_error(out,doc.raw_token(id),-32603,"asynchronous result exceeds the response limit",None)}
146	    if is_task&&(!supports||!ready){return append_error(out,doc.raw_token(id),-32021,"task support was not negotiated for this request",Some(r#"{"requiredCapabilities":{"io.modelcontextprotocol/tasks":{}}}"#))}
147	    append_async_payload(out,doc,id,payload,modern,is_error)
148	}
149	fn append_async_payload(out:&mut JsonBuffer,request:&JsonDocument<'_>,id:usize,payload:&[u8],modern:bool,is_error:bool)->Result<(),ProtocolError>{
150	    lit(out,"{\"jsonrpc\":\"2.0\",\"id\":")?;append_raw(out,request,id)?;
151	    if is_error{lit(out,",\"error\":")?;out.append(payload).map_err(ProtocolError::Buffer)?;return lit(out,"}");}
152	    lit(out,",\"result\":")?;if !modern{out.append(payload).map_err(ProtocolError::Buffer)?;return lit(out,"}");}
153	    let result=JsonDocument::parse(payload).map_err(|_|ProtocolError::InvalidInput)?;let root=result.root();lit(out,"{")?;let mut first=true;
154	    let mut key=result.token(root).and_then(|t|t.first_child);
155	    while let Some(k)=key{let value=result.token(k).and_then(|t|t.next_sibling).ok_or(ProtocolError::InvalidInput)?;let next=result.token(value).and_then(|t|t.next_sibling);if !result.string_equals(k,b"_meta"){if !first{lit(out,",")?;}append_raw(out,&result,k)?;lit(out,":")?;append_raw(out,&result,value)?;first=false;}key=next;}
156	    if !first{lit(out,",")?;}lit(out,"\"_meta\":{")?;let meta=result.object_get(root,b"_meta");let mut meta_first=true;
157	    if let Some(meta)=meta{let mut key=result.token(meta).and_then(|t|t.first_child);while let Some(k)=key{let value=result.token(k).and_then(|t|t.next_sibling).ok_or(ProtocolError::InvalidInput)?;let next=result.token(value).and_then(|t|t.next_sibling);if !result.string_equals(k,b"io.modelcontextprotocol/serverInfo"){if !meta_first{lit(out,",")?;}append_raw(out,&result,k)?;lit(out,":")?;append_raw(out,&result,value)?;meta_first=false;}key=next;}}
158	    if !meta_first{lit(out,",")?;}lit(out,r#""io.modelcontextprotocol/serverInfo":{"name":"Vexel","version":"0.1.0"}}}"#)?;lit(out,"}")
159	}
160	fn append_task_method<A:AsyncBackend+?Sized>(modern:bool,doc:&JsonDocument<'_>,params:Option<usize>,id:usize,method:&str,async_backend:Option<&mut A>,out:&mut JsonBuffer)->Result<(),ProtocolError>{
161	    let Some(a)=async_backend else{return append_error(out,doc.raw_token(id),-32601,"method not found",None)};
162	    if !modern||!a.tasks_available(){return append_error(out,doc.raw_token(id),-32601,"method not found",None)}
163	    if !request_supports_tasks(doc,params){return append_error(out,doc.raw_token(id),-32021,"task support was not negotiated for this request",Some(r#"{"requiredCapabilities":{"io.modelcontextprotocol/tasks":{}}}"#));}
