 39	fn get(doc: &JsonDocument<'_>, object: usize, key: &[u8]) -> Option<usize> { doc.object_get(object, key) }
 40	fn string_is(doc: &JsonDocument<'_>, object: usize, key: &[u8], expected: &[u8]) -> bool { get(doc, object, key).is_some_and(|v| doc.string_equals(v, expected)) }
 41	fn optional_object(doc: &JsonDocument<'_>, object: usize, key: &[u8]) -> bool { get(doc, object, key).is_none_or(|v| doc.token(v).is_some_and(|t| t.kind == JsonType::Object)) }
 42	fn valid_string(doc: &JsonDocument<'_>, token: Option<usize>, nonempty: bool) -> bool {
 43	    let Some(token) = token else { return false; };
 44	    let Some(bytes) = doc.decoded_string(token) else { return false; };
 45	    (!nonempty || !bytes.is_empty()) && !bytes.contains(&0)
 46	}
 47	fn valid_timestamp(doc: &JsonDocument<'_>, object: usize, key: &[u8]) -> bool {
 48	    let Some(token) = get(doc, object, key) else { return false; };
 49	    let Some(v) = doc.decoded_string(token) else { return false; };
 50	    let Ok(s) = std::str::from_utf8(&v) else { return false; };
 51	    if v.contains(&0) || s.len() < 20 || s.len() > 63 || !s.is_ascii() { return false; }
 52	    let b = s.as_bytes();
 53	    if b[4] != b'-' || b[7] != b'-' || b[10] != b'T' || b[13] != b':' || b[16] != b':' { return false; }
 54	    for (i, c) in b.iter().take(19).enumerate() { if !matches!(i, 4|7|10|13|16) && !c.is_ascii_digit() { return false; } }
 55	    let n = |a: usize, z: usize| -> u32 { s[a..z].parse().unwrap_or(u32::MAX) };
 56	    let (year, month, day, hour, minute, second) = (n(0,4),n(5,7),n(8,10),n(11,13),n(14,16),n(17,19));
 57	    if year == 0 || !(1..=12).contains(&month) || hour > 23 || minute > 59 || second > 60 { return false; }
 58	    let mdays = [31, if year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) {29} else {28},31,30,31,30,31,31,30,31,30,31];
 59	    if day == 0 || day > mdays[(month-1) as usize] { return false; }
 60	    let mut i = 19;
 61	    if b.get(i) == Some(&b'.') { i += 1; let start=i; while b.get(i).is_some_and(u8::is_ascii_digit) { i+=1; } if i==start { return false; } }
 62	    if b.get(i) == Some(&b'Z') { return i+1 == b.len(); }
 63	    if i.checked_add(6) != Some(b.len()) || !matches!(b.get(i), Some(b'+')|Some(b'-')) || b.get(i+3) != Some(&b':') { return false; }
 64	    for (j,c) in b.iter().enumerate().skip(i+1) { if j != i+3 && !c.is_ascii_digit() { return false; } }
 65	    let zone_hour = u32::from(b[i+1]-b'0')*10+u32::from(b[i+2]-b'0');
 66	    let zone_minute = u32::from(b[i+4]-b'0')*10+u32::from(b[i+5]-b'0');
 67	    zone_hour <= 14 && zone_minute <= 59 && (zone_hour != 14 || zone_minute == 0)
 68	}
 69	fn valid_error(doc: &JsonDocument<'_>, object: usize) -> bool {
 70	    let Some(code) = get(doc, object, b"code") else { return false; };
 71	    doc.token(code).is_some_and(|t| t.kind == JsonType::Number) && doc.raw_token(code).is_some_and(|raw| !raw.iter().any(|b| matches!(b,b'.'|b'e'|b'E'))) && valid_string(doc, get(doc, object,b"message"), true)
 72	}
 73	fn valid_content(doc: &JsonDocument<'_>, token: Option<usize>) -> bool {
 74	    let Some(token)=token else{return false};
 75	    let Some(array)=doc.token(token) else{return false};
 76	    if array.kind != JsonType::Array { return false; }
 77	    let mut block=array.first_child;
 78	    while let Some(i)=block {
 79	        let Some(b)=doc.token(i) else{return false}; if b.kind!=JsonType::Object || !optional_object(doc,i,b"annotations"){return false;}
 80	        let Some(ty)=get(doc,i,b"type") else{return false}; if !valid_string(doc,Some(ty),true){return false;}
 81	        if doc.string_equals(ty,b"text") { if !valid_string(doc,get(doc,i,b"text"),false){return false;} }
 82	        else if doc.string_equals(ty,b"image")||doc.string_equals(ty,b"audio") { if !valid_string(doc,get(doc,i,b"data"),true)||!valid_string(doc,get(doc,i,b"mimeType"),true){return false;} }
 83	        else if doc.string_equals(ty,b"resource") {
 84	            let Some(r)=get(doc,i,b"resource") else{return false};
 85	            if doc.token(r).is_none_or(|t| t.kind!=JsonType::Object)||!optional_string(doc,r,b"uri",true)||!optional_string(doc,r,b"mimeType",true){return false;}
 86	            if !valid_string(doc,get(doc,r,b"uri"),true) {return false;}
 87	            let text=get(doc,r,b"text"); let blob=get(doc,r,b"blob");
 88	            if text.is_some()==blob.is_some() || text.is_some_and(|v|!valid_string(doc,Some(v),false)) || blob.is_some_and(|v|!valid_string(doc,Some(v),false)){return false;}
 89	        }
 90	        else if doc.string_equals(ty,b"resource_link") {
 91	            if !valid_string(doc,get(doc,i,b"uri"),true)||!valid_string(doc,get(doc,i,b"name"),true)||!optional_string(doc,i,b"title",false)||!optional_string(doc,i,b"description",false)||!optional_string(doc,i,b"mimeType",true){return false;}
 92	            if get(doc,i,b"icons").is_some_and(|v|doc.token(v).is_none_or(|t|t.kind!=JsonType::Array)) || get(doc,i,b"size").is_some_and(|v|doc.uint(v).is_none()){return false;}
 93	        } else {return false;}
 94	        block=b.next_sibling;
 95	    }
 96	    true
 97	}
 98	fn optional_string(doc:&JsonDocument<'_>,object:usize,key:&[u8],nonempty:bool)->bool { get(doc,object,key).is_none_or(|v|valid_string(doc,Some(v),nonempty)) }
 99	fn valid_call_result(doc:&JsonDocument<'_>,object:usize)->bool {
100	    if doc.token(object).is_none_or(|t|t.kind!=JsonType::Object)||!valid_content(doc,get(doc,object,b"content")){return false;}
101	    let bool_field=get(doc,object,b"isError").is_none_or(|v|doc.bool(v).is_some());
102	    let structured=get(doc,object,b"structuredContent").is_none_or(|v|doc.token(v).is_some_and(|t|t.kind==JsonType::Object));
103	    let kind=get(doc,object,b"resultType").is_none_or(|v|doc.string_equals(v,b"complete"));
104	    bool_field&&structured&&kind&&optional_object(doc,object,b"_meta")
105	}
106	fn valid_task_meta(doc:&JsonDocument<'_>,object:usize,allow_poll:bool)->bool {
107	    let Some(id)=get(doc,object,b"taskId") else{return false};
108	    if !valid_string(doc,Some(id),true)||doc.decoded_string(id).is_none_or(|s|s.len()>TASK_ID_LIMIT){return false;}
109	    let status=[b"working".as_slice(),b"completed",b"failed",b"cancelled"].iter().any(|s|string_is(doc,object,b"status",s));
110	    let Some(ttl)=get(doc,object,b"ttlMs").and_then(|v|doc.uint(v)) else{return false};
111	    if !status||!valid_timestamp(doc,object,b"createdAt")||!valid_timestamp(doc,object,b"lastUpdatedAt")||ttl==0||ttl>TASK_TTL_LIMIT{return false;}
112	    if let Some(p)=get(doc,object,b"pollIntervalMs") { let Some(n)=doc.uint(p) else{return false}; if !allow_poll||n==0||n>TASK_TTL_LIMIT{return false;} }
113	    if get(doc,object,b"statusMessage").is_some_and(|v|doc.token(v).is_none_or(|t|t.kind!=JsonType::String)) {return false;}
114	    optional_object(doc,object,b"_meta")
115	}
116	fn valid_terminal(doc:&JsonDocument<'_>,object:usize)->bool {
117	    let result=get(doc,object,b"result"); let error=get(doc,object,b"error");
118	    if string_is(doc,object,b"status",b"completed") { result.is_some()&&error.is_none()&&result.is_some_and(|v|valid_call_result(doc,v)) }
119	    else if string_is(doc,object,b"status",b"failed") { result.is_none()&&error.is_some_and(|v|valid_error(doc,v)) }
120	    else { result.is_none()&&error.is_none() }
121	}
122	fn valid_create_task(doc:&JsonDocument<'_>,object:usize)->bool { valid_task_meta(doc,object,true)&&get(doc,object,b"result").is_none()&&get(doc,object,b"error").is_none() }
123	fn valid_get_task(doc:&JsonDocument<'_>,object:usize)->bool { valid_task_meta(doc,object,false)&&valid_terminal(doc,object) }
124	fn valid_cancel_ack(doc:&JsonDocument<'_>,root:usize)->bool {
125	    if !string_is(doc,root,b"resultType",b"complete")||![b"taskId".as_slice(),b"status",b"createdAt",b"lastUpdatedAt",b"ttlMs",b"result",b"error"].iter().all(|k|get(doc,root,k).is_none())||!optional_object(doc,root,b"_meta"){return false;}
126	    let Some(token)=doc.token(root) else{return false}; let mut key=token.first_child;
127	    while let Some(k)=key {let Some(value)=doc.token(k).and_then(|t|t.next_sibling) else{return false}; if !doc.string_equals(k,b"resultType")&&!doc.string_equals(k,b"_meta"){return false;} key=doc.token(value).and_then(|t|t.next_sibling);}
128	    true
129	}
