131	pub fn legacy_progress(raw_token:&[u8], progress:u32, prior:&mut i64, message:&str, out:&mut JsonBuffer)->Result<(),ProgressError> {
132	    if raw_token.is_empty()||raw_token.len()>PROGRESS_TOKEN_LIMIT{return Err(ProgressError::InvalidToken);}
133	    if progress>1000||i64::from(progress)<=*prior{return Err(ProgressError::InvalidProgress);}
134	    if message.len()>PROGRESS_MESSAGE_LIMIT{return Err(ProgressError::InvalidMessage);}
135	    let token_doc=JsonDocument::parse(raw_token).map_err(|_|ProgressError::InvalidToken)?;
136	    let token_type=token_doc.token(token_doc.root()).map(|t|t.kind);
137	    let scalar=matches!(token_type,Some(JsonType::String)) || (token_type==Some(JsonType::Number)&&token_doc.raw_token(token_doc.root()).is_some_and(|r|!r.iter().any(|b|matches!(b,b'.'|b'e'|b'E'))));
138	    if !scalar{return Err(ProgressError::InvalidToken);}
139	    let mut payload=JsonBuffer::new(128,MAX_BYTES).map_err(|_|ProgressError::Buffer)?;
140	    payload.literal("{\"jsonrpc\":\"2.0\",\"method\":\"notifications/progress\",\"params\":{\"progressToken\":").map_err(|_|ProgressError::Buffer)?;
141	    payload.append(raw_token).map_err(|_|ProgressError::Buffer)?;
142	    payload.literal(",\"progress\":").map_err(|_|ProgressError::Buffer)?;
143	    append_u32(&mut payload,progress).map_err(|_|ProgressError::Buffer)?;
144	    payload.literal(",\"total\":1000,\"message\":").map_err(|_|ProgressError::Buffer)?;
145	    payload.quoted(message.as_bytes()).map_err(|_|ProgressError::Buffer)?; payload.literal("}}").map_err(|_|ProgressError::Buffer)?;
146	    out.append(payload.as_bytes()).map_err(|_|ProgressError::Buffer)?; *prior=i64::from(progress); Ok(())
147	}
