117	fn type_matches(doc: &JsonDocument<'_>, token: usize, kind: &str) -> bool {
118	    let Some(item) = doc.token(token) else { return false; };
119	    match kind {
120	        "string" => item.kind == JsonType::String,
121	        "object" => item.kind == JsonType::Object,
122	        "array" => item.kind == JsonType::Array,
123	        "boolean" => matches!(item.kind, JsonType::True | JsonType::False),
124	        "number" => item.kind == JsonType::Number,
125	        "integer" => doc.uint(token).is_some(),
126	        _ => false,
127	    }
128	}
