  8	fn json(bytes: &[u8]) -> JsonDocument<'_> { JsonDocument::parse(bytes).expect("valid JSON") }
  9	fn assert_response(request: &str, response: &[u8]) {
 10	    let req = json(request.as_bytes());
 11	    let res = json(response);
 12	    let root = res.root();
 13	    assert_eq!(res.string_equals(res.object_get(root, b"jsonrpc").unwrap(), b"2.0"), true);
 14	    let req_id = req.object_get(req.root(), b"id").unwrap();
 15	    let res_id = res.object_get(root, b"id").unwrap();
 16	    assert_eq!(req.raw_token(req_id), res.raw_token(res_id), "original JSON-RPC id bytes are preserved");
 17	    let result = res.object_get(root, b"result");
 18	    let error = res.object_get(root, b"error");
 19	    assert_ne!(result.is_some(), error.is_some(), "response has exactly one of result/error");
 20	    assert_eq!(res.token(result.or(error).unwrap()).unwrap().kind, JsonType::Object);
 21	}
