 22	pub fn validate_async_payload(data: &[u8], kind: AsyncPayloadKind) -> Result<bool, ()> {
 23	    if data.is_empty() || data.len() > MAX_BYTES { return Err(()); }
 24	    let doc = JsonDocument::parse(data).map_err(|_| ())?;
 25	    let root = doc.root();
 26	    if doc.token(root).is_none_or(|t| t.kind != JsonType::Object) { return Err(()); }
 27	    let task = match kind {
 28	        AsyncPayloadKind::Error => valid_error(&doc, root),
 29	        AsyncPayloadKind::ToolResult => {
 30	            if string_is(&doc, root, b"resultType", b"task") { valid_create_task(&doc, root) }
 31	            else { valid_call_result(&doc, root) }
 32	        }
 33	        AsyncPayloadKind::TaskGet => string_is(&doc, root, b"resultType", b"complete") && valid_get_task(&doc, root),
 34	        AsyncPayloadKind::TaskCancel => valid_cancel_ack(&doc, root),
 35	    };
 36	    if task { Ok(kind == AsyncPayloadKind::ToolResult && string_is(&doc, root, b"resultType", b"task")) } else { Err(()) }
 37	}
