149	fn append_u32(out:&mut JsonBuffer,value:u32)->Result<(),vexel_json::JsonBufferError>{
150	    let mut digits=[0u8;10];let mut n=value;let mut at=digits.len();
151	    loop{at-=1;digits[at]=b'0'+(n%10) as u8;n/=10;if n==0{break;}}
152	    out.append(&digits[at..])
153	}

138	fn async_callback_response(doc:&JsonDocument<'_>,id:usize,modern:bool,supports:bool,ready:bool,kind:AsyncPayloadKind,disposition:AsyncDisposition,payload:&[u8],out:&mut JsonBuffer)->Result<(),ProtocolError>{
139	    if disposition==AsyncDisposition::Deferred {if modern{return append_error(out,doc.raw_token(id),-32603,"deferred response is unavailable for the current protocol",None)}return Ok(());}
140	    if disposition==AsyncDisposition::Failed{return append_error(out,doc.raw_token(id),-32603,"asynchronous protocol operation failed",None)}
141	    if !matches!(disposition,AsyncDisposition::Result|AsyncDisposition::Error){return append_error(out,doc.raw_token(id),-32603,"invalid asynchronous protocol disposition",None)}
142	    let is_error=disposition==AsyncDisposition::Error;let validation_kind=if is_error{AsyncPayloadKind::Error}else{kind};
143	    let is_task=match validate_async_payload(payload,validation_kind){Ok(v)=>v,Err(())=>return append_error(out,doc.raw_token(id),-32603,"asynchronous backend returned invalid JSON",None)};
144	    let overhead=512usize.checked_add(doc.raw_token(id).map_or(0,|v|v.len())).ok_or(ProtocolError::InvalidInput)?;
145	    if overhead>=LIMIT||payload.len()>LIMIT-overhead{return append_error(out,doc.raw_token(id),-32603,"asynchronous result exceeds the response limit",None)}
146	    if is_task&&(!supports||!ready){return append_error(out,doc.raw_token(id),-32021,"task support was not negotiated for this request",Some(r#"{"requiredCapabilities":{"io.modelcontextprotocol/tasks":{}}}"#))}
147	    append_async_payload(out,doc,id,payload,modern,is_error)
148	}
149	fn append_async_payload(out:&mut JsonBuffer,request:&JsonDocument<'_>,id:usize,payload:&[u8],modern:bool,is_error:bool)->Result<(),ProtocolError>{
150	    lit(out,"{\"jsonrpc\":\"2.0\",\"id\":")?;append_raw(out,request,id)?;
151	    if is_error{lit(out,",\"error\":")?;out.append(payload).map_err(ProtocolError::Buffer)?;return lit(out,"}");}
152	    lit(out,",\"result\":")?;if !modern{out.append(payload).map_err(ProtocolError::Buffer)?;return lit(out,"}");}
153	    let result=JsonDocument::parse(payload).map_err(|_|ProtocolError::InvalidInput)?;let root=result.root();lit(out,"{")?;let mut first=true;
154	    let mut key=result.token(root).and_then(|t|t.first_child);
155	    while let Some(k)=key{let value=result.token(k).and_then(|t|t.next_sibling).ok_or(ProtocolError::InvalidInput)?;let next=result.token(value).and_then(|t|t.next_sibling);if !result.string_equals(k,b"_meta"){if !first{lit(out,",")?;}append_raw(out,&result,k)?;lit(out,":")?;append_raw(out,&result,value)?;first=false;}key=next;}
156	    if !first{lit(out,",")?;}lit(out,"\"_meta\":{")?;let meta=result.object_get(root,b"_meta");let mut meta_first=true;
157	    if let Some(meta)=meta{let mut key=result.token(meta).and_then(|t|t.first_child);while let Some(k)=key{let value=result.token(k).and_then(|t|t.next_sibling).ok_or(ProtocolError::InvalidInput)?;let next=result.token(value).and_then(|t|t.next_sibling);if !result.string_equals(k,b"io.modelcontextprotocol/serverInfo"){if !meta_first{lit(out,",")?;}append_raw(out,&result,k)?;lit(out,":")?;append_raw(out,&result,value)?;meta_first=false;}key=next;}}
158	    if !meta_first{lit(out,",")?;}lit(out,r#""io.modelcontextprotocol/serverInfo":{"name":"Vexel","version":"0.1.0"}}}"#)?;lit(out,"}")
159	}
160	fn append_task_method<A:AsyncBackend+?Sized>(modern:bool,doc:&JsonDocument<'_>,params:Option<usize>,id:usize,method:&str,async_backend:Option<&mut A>,out:&mut JsonBuffer)->Result<(),ProtocolError>{
161	    let Some(a)=async_backend else{return append_error(out,doc.raw_token(id),-32601,"method not found",None)};
162	    if !modern||!a.tasks_available(){return append_error(out,doc.raw_token(id),-32601,"method not found",None)}
163	    if !request_supports_tasks(doc,params){return append_error(out,doc.raw_token(id),-32021,"task support was not negotiated for this request",Some(r#"{"requiredCapabilities":{"io.modelcontextprotocol/tasks":{}}}"#));}
164	    let task_id=params.and_then(|p|doc.object_get(p,b"taskId")).and_then(|v|doc.decoded_string(v));
165	    let Some(task_id)=task_id.filter(|v|!v.is_empty()&&v.len()<=1024&&!v.contains(&0)) else{return append_error(out,doc.raw_token(id),-32602,"task method requires a valid taskId",None)};
166	    let task_id=String::from_utf8(task_id).map_err(|_|ProtocolError::InvalidInput)?;
167	    let (disposition,payload)=if method=="tasks/get"{a.get_task(doc,&task_id)}else{a.cancel_task(doc,&task_id)};
168	    async_callback_response(doc,id,true,true,true,if method=="tasks/get"{AsyncPayloadKind::TaskGet}else{AsyncPayloadKind::TaskCancel},disposition,&payload,out)
169	}
170	fn append_resource_read<B:ProtocolBackend+?Sized>(session:&mut ProtocolSession,doc:&JsonDocument<'_>,params:Option<usize>,id:usize,backend:Option<&mut B>,out:&mut JsonBuffer)->Result<(),ProtocolError>{
171	    let uri=params.and_then(|p|doc.object_get(p,b"uri")).and_then(|t|doc.decoded_string(t));let Some(uri)=uri.filter(|v|v.len()<256&&!v.contains(&0)) else{return append_error(out,doc.raw_token(id),-32602,"resources/read requires a URI",None)};
172	    let uri=String::from_utf8(uri).map_err(|_|ProtocolError::InvalidInput)?;let contents=backend.and_then(|b|b.read_resource(doc,&uri));let Some(contents)=contents else{return append_error(out,doc.raw_token(id),-32002,"resource not found",None)};
173	    response_prefix(out,doc,id)?;lit(out,"\"contents\":")?;out.append(&contents).map_err(ProtocolError::Buffer)?;response_suffix(out,session.modern)
174	}
