177	    let Ok(doc)=JsonDocument::parse(line) else{return true};let root=doc.root();if doc.token(root).is_none_or(|t|t.kind!=JsonType::Object){return true;}
178	    let method=doc.object_get(root,b"method");let known=method.is_some_and(|m|[b"notifications/initialized".as_slice(),b"notifications/cancelled",b"notifications/progress"].iter().any(|v|doc.string_equals(m,v)));
179	    if known {false}else{doc.object_get(root,b"id").is_some()||true}
