 78	pub fn validate_tool_arguments(doc: &JsonDocument<'_>, arguments: usize, tool_name: &str) -> Result<(), ToolValidationError> {
 79	    let Some(args) = doc.token(arguments) else { return Err(ToolValidationError::InvalidArguments); };
 80	    if args.kind != JsonType::Object { return Err(ToolValidationError::InvalidArguments); }
 81	    let Some(tool) = TOOLS.iter().find(|t| t.name == tool_name) else { return Err(ToolValidationError::UnknownTool); };
 82	    let mut key = args.first_child;
 83	    while let Some(key_index) = key {
 84	        let Some(value) = doc.token(key_index).and_then(|t| t.next_sibling) else { return Err(ToolValidationError::InvalidArguments); };
 85	        let Some(key_bytes) = doc.decoded_string(key_index) else { return Err(ToolValidationError::InvalidArguments); };
 86	        let Ok(field) = std::str::from_utf8(&key_bytes) else { return Err(ToolValidationError::UnexpectedArgument); };
 87	        let Some(expected) = tool.fields.split(';').find_map(|field_spec| {
 88	            let (name, kind) = field_spec.split_once(':')?;
 89	            (name == field).then_some(kind)
 90	        }) else { return Err(ToolValidationError::UnexpectedArgument); };
 91	        if !expected.split('|').any(|kind| type_matches(doc, value, kind)) { return Err(ToolValidationError::WrongType); }
 92	        if tool.name == "native_timeline_set_loop" && field == "mode" {
 93	            let valid = [b"once".as_slice(), b"loop", b"ping_pong"].iter().any(|v| doc.string_equals(value, v));
 94	            if !valid { return Err(ToolValidationError::InvalidLoopMode); }
 95	        }
 96	        if tool.name == "element_add" && field == "attributes" {
 97	            let attrs = doc.token(value).ok_or(ToolValidationError::InvalidArguments)?;
 98	            let mut child = attrs.first_child;
 99	            while let Some(k) = child {
100	                let Some(v) = doc.token(k).and_then(|t| t.next_sibling) else { return Err(ToolValidationError::InvalidTemplateAttributes); };
101	                if doc.token(k).is_none_or(|t| t.kind != JsonType::String) || doc.token(v).is_none_or(|t| t.kind != JsonType::String) { return Err(ToolValidationError::InvalidTemplateAttributes); }
102	                child = doc.token(v).and_then(|t| t.next_sibling);
103	            }
104	        }
105	        if tool.name == "transaction" && field == "edits" {
106	            let count = doc.token(value).map_or(0, |t| t.child_count);
107	            if !(1..=64).contains(&count) { return Err(ToolValidationError::InvalidTransactionLength); }
108	        }
109	        key = doc.token(value).and_then(|t| t.next_sibling);
110	    }
111	    for required in tool.required.split(',').filter(|s| !s.is_empty()) {
112	        if doc.object_get(arguments, required.as_bytes()).is_none() { return Err(ToolValidationError::MissingRequired); }
113	    }
114	    Ok(())
115	}
