 30	    if (!mcp_json_buffer_literal(out, "{\"jsonrpc\":\"2.0\",\"id\":")) return false;
 31	    if (id == NULL) {
 32	        if (!mcp_json_buffer_literal(out, "null")) return false;
 33	    } else if (!mcp_json_buffer_append(out, id, id_length)) return false;
 34	    if (!mcp_json_buffer_literal(out, ",\"error\":{\"code\":")) return false;
 35	    char number[32];
 36	    int amount = snprintf(number, sizeof(number), "%d", code);
 37	    if (amount < 0 || (size_t)amount >= sizeof(number) ||
 38	        !mcp_json_buffer_append(out, number, (size_t)amount) ||
 39	        !mcp_json_buffer_literal(out, ",\"message\":" ) ||
 40	        !mcp_json_buffer_quoted(out, message, strlen(message))) return false;
 41	    if (data != NULL && (!mcp_json_buffer_literal(out, ",\"data\":" ) ||
 42	                         !mcp_json_buffer_literal(out, data))) return false;
 43	    return mcp_json_buffer_literal(out, "}}");
 44	}
