189	static bool append_async_payload(mcp_json_buffer *out, const mcp_json_doc *doc,
190	    size_t id, const char *payload, size_t payload_length, bool modern,
191	    bool is_error)
192	{
193	    if (payload_length == 0U || payload_length > MCP_RESPONSE_LIMIT) return false;
194	    if (is_error) {
195	        return mcp_json_buffer_literal(out, "{\"jsonrpc\":\"2.0\",\"id\":") &&
196	            mcp_json_buffer_raw_token(out, doc, id) &&
197	            mcp_json_buffer_literal(out, ",\"error\":") &&
198	            mcp_json_buffer_append(out, payload, payload_length) &&
199	            mcp_json_buffer_literal(out, "}");
200	    }
201	    if (!mcp_json_buffer_literal(out, "{\"jsonrpc\":\"2.0\",\"id\":") ||
202	        !mcp_json_buffer_raw_token(out, doc, id) ||
203	        !mcp_json_buffer_literal(out, ",\"result\":")) return false;
204	    if (!modern) return mcp_json_buffer_append(out, payload, payload_length) &&
205	        mcp_json_buffer_literal(out, "}");
206	
207	    mcp_json_doc result = {0};
208	    if (!mcp_json_parse((const uint8_t *)payload, payload_length, &result)) return false;
209	    size_t root = result.root;
210	    size_t meta = mcp_json_object_get(&result, root, "_meta");
211	    bool okay = mcp_json_buffer_literal(out, "{");
212	    bool first = true;
213	    for (size_t key = result.tokens[root].first_child;
214	         okay && key != MCP_JSON_NO_TOKEN;) {
215	        size_t value = result.tokens[key].next_sibling;
216	        if (value == MCP_JSON_NO_TOKEN) { okay = false; break; }
217	        size_t next = result.tokens[value].next_sibling;
218	        if (!mcp_json_string_equals(&result, key, "_meta")) {
219	            okay = (first || mcp_json_buffer_literal(out, ",")) &&
220	                mcp_json_buffer_raw_token(out, &result, key) &&
221	                mcp_json_buffer_literal(out, ":") &&
222	                mcp_json_buffer_raw_token(out, &result, value);
223	            first = false;
224	        }
225	        key = next;
226	    }
227	    if (okay) okay = (first || mcp_json_buffer_literal(out, ",")) &&
228	        mcp_json_buffer_literal(out, "\"_meta\":{");
229	    bool meta_first = true;
230	    if (okay && meta != MCP_JSON_NO_TOKEN) {
231	        for (size_t key = result.tokens[meta].first_child;
232	             okay && key != MCP_JSON_NO_TOKEN;) {
233	            size_t value = result.tokens[key].next_sibling;
234	            if (value == MCP_JSON_NO_TOKEN) { okay = false; break; }
235	            size_t next = result.tokens[value].next_sibling;
236	            if (!mcp_json_string_equals(&result, key,
237	                    "io.modelcontextprotocol/serverInfo")) {
238	                okay = (meta_first || mcp_json_buffer_literal(out, ",")) &&
239	                    mcp_json_buffer_raw_token(out, &result, key) &&
240	                    mcp_json_buffer_literal(out, ":") &&
241	                    mcp_json_buffer_raw_token(out, &result, value);
242	                meta_first = false;
243	            }
244	            key = next;
245	        }
246	    }
247	    if (okay) okay = (meta_first || mcp_json_buffer_literal(out, ",")) &&
248	        mcp_json_buffer_literal(out,
249	            "\"io.modelcontextprotocol/serverInfo\":{\"name\":\"Vexel\","
250	            "\"version\":\"0.1.0\"}}}");
251	    mcp_json_doc_destroy(&result);
252	    return okay && mcp_json_buffer_literal(out, "}");
253	}
