255	static bool async_callback_response(mcp_protocol_session *session,
256	    const mcp_json_doc *doc, size_t id, bool modern, bool supports_tasks,
257	    bool tasks_ready, mcp_protocol_async_payload_kind payload_kind,
258	    mcp_protocol_async_disposition disposition, mcp_json_buffer *payload,
259	    mcp_json_buffer *out)
260	{
261	    if (disposition == MCP_PROTOCOL_ASYNC_DEFERRED) {
262	        if (modern) return append_error(out,
263	            (const char *)doc->source + doc->tokens[id].start,
264	            doc->tokens[id].end - doc->tokens[id].start, -32603,
265	            "deferred response is unavailable for the current protocol", NULL);
266	        return true;
267	    }
268	    if (disposition == MCP_PROTOCOL_ASYNC_FAILED) return append_error(out,
269	        (const char *)doc->source + doc->tokens[id].start,
270	        doc->tokens[id].end - doc->tokens[id].start, -32603,
271	        "asynchronous protocol operation failed", NULL);
272	    bool is_error = disposition == MCP_PROTOCOL_ASYNC_ERROR;
273	    if (disposition != MCP_PROTOCOL_ASYNC_RESULT && !is_error)
274	        return append_error(out,
275	            (const char *)doc->source + doc->tokens[id].start,
276	            doc->tokens[id].end - doc->tokens[id].start, -32603,
277	            "invalid asynchronous protocol disposition", NULL);
278	    bool is_task = false;
279	    mcp_protocol_async_payload_kind validation_kind = is_error ?
280	        MCP_PROTOCOL_ASYNC_PAYLOAD_ERROR : payload_kind;
281	    if (!mcp_protocol_async_validate_payload(payload->data, payload->length,
282	                                            validation_kind, &is_task))
283	        return append_error(out,
284	            (const char *)doc->source + doc->tokens[id].start,
285	            doc->tokens[id].end - doc->tokens[id].start, -32603,
286	            "asynchronous backend returned invalid JSON", NULL);
287	    size_t id_length = doc->tokens[id].end - doc->tokens[id].start;
288	    size_t overhead = 512U + id_length;
289	    if (overhead >= MCP_RESPONSE_LIMIT ||
290	        payload->length > MCP_RESPONSE_LIMIT - overhead)
291	        return append_error(out,
292	            (const char *)doc->source + doc->tokens[id].start,
293	            id_length, -32603, "asynchronous result exceeds the response limit", NULL);
294	    if (is_task && (!supports_tasks || !tasks_ready)) return append_error(out,
295	        (const char *)doc->source + doc->tokens[id].start,
296	        doc->tokens[id].end - doc->tokens[id].start, -32021,
297	        "task support was not negotiated for this request",
298	        "{\"requiredCapabilities\":{\"io.modelcontextprotocol/tasks\":{}}}");
299	    (void)session;
300	    return append_async_payload(out, doc, id, payload->data, payload->length,
301	                                modern, is_error);
302	}
