304	static bool append_tool_call(mcp_protocol_session *session, const mcp_json_doc *doc,
305	                             size_t params, size_t id, const mcp_protocol_backend *backend,
306	                             const mcp_protocol_async_backend *async_backend,
307	                             mcp_json_buffer *out)
308	{
309	    size_t name_token = mcp_json_object_get(doc, params, "name");
310	    size_t args = mcp_json_object_get(doc, params, "arguments");
311	    char name[64];
312	    size_t name_length = 0U;
313	    if (!mcp_json_string_copy(doc, name_token, name, sizeof(name) - 1U, &name_length) ||
314	        name_length == 0U || args == MCP_JSON_NO_TOKEN) {
315	        return append_error(out, (const char *)doc->source + doc->tokens[id].start,
316	            doc->tokens[id].end - doc->tokens[id].start, -32602,
317	            "tools/call requires a tool name and arguments", NULL);
318	    }
319	    name[name_length] = '\0';
320	    const char *validation_error = NULL;
321	    if (!mcp_tool_validate(doc, args, name, &validation_error)) {
322	        return append_text_tool_error(out, doc, id, session->modern,
323	            validation_error == NULL ? "invalid tool arguments" : validation_error,
324	            strcmp(validation_error == NULL ? "" : validation_error, "unknown tool") == 0 ?
325	            "unknown_tool" : "invalid_arguments");
326	    }
327	    if (async_backend != NULL && async_backend->call_tool != NULL) {
328	        mcp_json_buffer payload = {0};
329	        bool tasks_ready = mcp_protocol_async_tasks_ready(async_backend);
330	        bool supports_tasks = session->modern && request_supports_tasks(doc, params) &&
331	            tasks_ready;
332	        if (!mcp_json_buffer_init(&payload, 128U, MCP_RESPONSE_LIMIT)) return false;
333	        mcp_protocol_async_disposition disposition = async_backend->call_tool(
334	            async_backend->context, doc, args, name, session->modern,
335	            supports_tasks, &payload);
336	        if (disposition != MCP_PROTOCOL_ASYNC_UNHANDLED) {
337	            bool emitted = async_callback_response(session, doc, id,
338	                session->modern, supports_tasks, tasks_ready,
339	                MCP_PROTOCOL_ASYNC_PAYLOAD_TOOL_RESULT, disposition, &payload, out);
340	            mcp_json_buffer_destroy(&payload);
341	            return emitted;
342	        }
343	        mcp_json_buffer_destroy(&payload);
344	    }
345	    if (backend == NULL || backend->call_tool == NULL) return append_text_tool_error(out,
346	        doc, id, session->modern, "Vexel broker is unavailable", "broker_unavailable");
347	    mcp_tool_response result = {0};
348	    if (!mcp_json_buffer_init(&result.structured_json, 128U, MCP_RESPONSE_LIMIT) ||
349	        !mcp_json_buffer_init(&result.content_json, 128U, MCP_RESPONSE_LIMIT)) {
350	        mcp_json_buffer_destroy(&result.structured_json);
351	        mcp_json_buffer_destroy(&result.content_json);
352	        return false;
353	    }
354	    bool okay = backend->call_tool(backend->context, doc, args, name, &result);
355	    if (!okay || result.structured_json.length == 0U) {
356	        mcp_json_buffer_destroy(&result.structured_json);
357	        mcp_json_buffer_destroy(&result.content_json);
358	        return append_text_tool_error(out, doc, id, session->modern,
359	                                      "The tool could not complete its request", "tool_failed");
360	    }
361	    bool response_okay = append_response_prefix(out, doc, id) &&
362	        mcp_json_buffer_literal(out, "\"content\":");
363	    if (response_okay && result.content_json.length > 0U) {
364	        response_okay = mcp_json_buffer_append(out, result.content_json.data,
365	                                               result.content_json.length);
366	    } else if (response_okay) {
367	        const char *fallback = result.is_error ? "Tool request failed" : "Tool completed.";
368	        response_okay = mcp_json_buffer_literal(out, "[{\"type\":\"text\",\"text\":" ) &&
369	            mcp_json_buffer_quoted(out, fallback, strlen(fallback)) &&
370	            mcp_json_buffer_literal(out, "}]" );
371	    }
372	    if (response_okay) response_okay = mcp_json_buffer_literal(out, ",\"structuredContent\":") &&
373	        mcp_json_buffer_append(out, result.structured_json.data, result.structured_json.length) &&
374	        mcp_json_buffer_literal(out, result.is_error ? ",\"isError\":true" : ",\"isError\":false") &&
375	        append_response_suffix(out, session->modern);
376	    mcp_json_buffer_destroy(&result.structured_json);
377	    mcp_json_buffer_destroy(&result.content_json);
378	    return response_okay;
379	}
