396	        backend->read_resource(backend->context, doc, uri, &contents);
397	    bool response_okay = okay ? append_response_prefix(out, doc, id) &&
398	        mcp_json_buffer_literal(out, "\"contents\":" ) &&
399	        mcp_json_buffer_append(out, contents.data, contents.length) &&
400	        append_response_suffix(out, session->modern) :
401	        append_error(out, (const char *)doc->source + doc->tokens[id].start,
