407	static bool append_task_method(mcp_protocol_session *session,
408	    const mcp_json_doc *doc, size_t params, size_t id, const char *method,
409	    const mcp_protocol_async_backend *async_backend, mcp_json_buffer *out)
410	{
411	    if (!session->modern || !mcp_protocol_async_tasks_ready(async_backend))
412	        return append_error(out, (const char *)doc->source + doc->tokens[id].start,
413	            doc->tokens[id].end - doc->tokens[id].start, -32601,
414	            "method not found", NULL);
415	    if (!request_supports_tasks(doc, params)) return append_error(out,
416	        (const char *)doc->source + doc->tokens[id].start,
417	        doc->tokens[id].end - doc->tokens[id].start, -32021,
418	        "task support was not negotiated for this request",
419	        "{\"requiredCapabilities\":{\"io.modelcontextprotocol/tasks\":{}}}");
420	    char task_id[1025];
421	    if (!mcp_protocol_async_task_id(doc, params, task_id, sizeof(task_id)))
422	        return append_error(out, (const char *)doc->source + doc->tokens[id].start,
423	            doc->tokens[id].end - doc->tokens[id].start, -32602,
424	            "task method requires a valid taskId", NULL);
425	    mcp_json_buffer payload = {0};
426	    if (!mcp_json_buffer_init(&payload, 128U, MCP_RESPONSE_LIMIT)) return false;
427	    mcp_protocol_async_disposition disposition = strcmp(method, "tasks/get") == 0 ?
428	        async_backend->get_task(async_backend->context, doc, task_id, &payload) :
429	        async_backend->cancel_task(async_backend->context, doc, task_id, &payload);
430	    bool is_cancel = strcmp(method, "tasks/cancel") == 0;
431	    bool emitted = async_callback_response(session, doc, id, true, true, true,
432	        is_cancel ? MCP_PROTOCOL_ASYNC_PAYLOAD_TASK_CANCEL :
433	            MCP_PROTOCOL_ASYNC_PAYLOAD_TASK_GET,
434	        disposition, &payload, out);
435	    mcp_json_buffer_destroy(&payload);
436	    return emitted;
437	}
