 75	static bool valid_timestamp(const mcp_json_doc *doc, size_t object,
 76	                            const char *key)
 77	{
 78	    char value[64];
 79	    size_t length = 0U;
 80	    if (!string_field(doc, object, key, value, sizeof(value) - 1U, &length) ||
 81	        length < 20U) return false;
 82	    if (value[4] != '-' || value[7] != '-' || value[10] != 'T' ||
 83	        value[13] != ':' || value[16] != ':') return false;
 84	    for (size_t index = 0U; index < 19U; ++index) {
 85	        if (index == 4U || index == 7U || index == 10U ||
 86	            index == 13U || index == 16U) continue;
 87	        if (value[index] < '0' || value[index] > '9') return false;
 88	    }
 89	    unsigned year = (unsigned)(value[0] - '0') * 1000U +
 90	        (unsigned)(value[1] - '0') * 100U +
 91	        (unsigned)(value[2] - '0') * 10U + (unsigned)(value[3] - '0');
 92	    unsigned month = (unsigned)(value[5] - '0') * 10U + (unsigned)(value[6] - '0');
 93	    unsigned day = (unsigned)(value[8] - '0') * 10U + (unsigned)(value[9] - '0');
 94	    unsigned hour = (unsigned)(value[11] - '0') * 10U + (unsigned)(value[12] - '0');
 95	    unsigned minute = (unsigned)(value[14] - '0') * 10U + (unsigned)(value[15] - '0');
 96	    unsigned second = (unsigned)(value[17] - '0') * 10U + (unsigned)(value[18] - '0');
 97	    static const unsigned month_days[] = {31U, 28U, 31U, 30U, 31U, 30U,
 98	        31U, 31U, 30U, 31U, 30U, 31U};
 99	    if (year == 0U || month == 0U || month > 12U || hour > 23U ||
100	        minute > 59U || second > 60U) return false;
101	    unsigned max_day = month_days[month - 1U];
102	    if (month == 2U && (year % 4U == 0U && (year % 100U != 0U || year % 400U == 0U)))
103	        max_day++;
104	    if (day == 0U || day > max_day) return false;
105	    size_t cursor = 19U;
106	    if (cursor < length && value[cursor] == '.') {
107	        cursor++;
108	        size_t fraction_start = cursor;
109	        while (cursor < length && value[cursor] >= '0' && value[cursor] <= '9') cursor++;
110	        if (cursor == fraction_start) return false;
111	    }
112	    if (cursor < length && value[cursor] == 'Z') return cursor + 1U == length;
113	    if (cursor + 6U != length ||
114	        (value[cursor] != '+' && value[cursor] != '-') ||
115	        value[cursor + 3U] != ':') return false;
116	    for (size_t index = cursor + 1U; index < length; ++index) {
117	        if (index == cursor + 3U) continue;
118	        if (value[index] < '0' || value[index] > '9') return false;
119	    }
120	    unsigned zone_hour = (unsigned)(value[cursor + 1U] - '0') * 10U +
121	        (unsigned)(value[cursor + 2U] - '0');
122	    unsigned zone_minute = (unsigned)(value[cursor + 4U] - '0') * 10U +
123	        (unsigned)(value[cursor + 5U] - '0');
124	    return zone_hour <= 14U && zone_minute <= 59U &&
125	        (zone_hour != 14U || zone_minute == 0U);
126	}
