240	static bool validate_task_metadata(const mcp_json_doc *doc, size_t object,
241	                                   bool allow_poll)
242	{
243	    char task_id[ASYNC_TASK_ID_LIMIT + 1U];
244	    size_t id_length = 0U;
245	    uint64_t ttl = 0U, poll = 0U;
246	    if (!string_field(doc, object, "taskId", task_id, ASYNC_TASK_ID_LIMIT,
247	                      &id_length) || id_length == 0U ||
248	        (!task_status(doc, object, "working") &&
249	         !task_status(doc, object, "completed") &&
250	         !task_status(doc, object, "failed") &&
251	         !task_status(doc, object, "cancelled")) ||
252	        !valid_timestamp(doc, object, "createdAt") ||
253	        !valid_timestamp(doc, object, "lastUpdatedAt") ||
254	        !mcp_json_uint(doc, mcp_json_object_get(doc, object, "ttlMs"), &ttl) ||
255	        ttl == 0U || ttl > ASYNC_TASK_TTL_LIMIT) return false;
256	    size_t poll_token = mcp_json_object_get(doc, object, "pollIntervalMs");
257	    if (poll_token != MCP_JSON_NO_TOKEN &&
258	        (!allow_poll || !mcp_json_uint(doc, poll_token, &poll) || poll == 0U ||
259	         poll > ASYNC_TASK_TTL_LIMIT)) return false;
260	    size_t status_message = mcp_json_object_get(doc, object, "statusMessage");
261	    size_t meta = mcp_json_object_get(doc, object, "_meta");
262	    if (status_message != MCP_JSON_NO_TOKEN &&
263	        doc->tokens[status_message].type != MCP_JSON_STRING) return false;
264	    if (meta != MCP_JSON_NO_TOKEN && doc->tokens[meta].type != MCP_JSON_OBJECT)
265	        return false;
266	    return true;
267	}
