295	static bool validate_cancel_ack(const mcp_json_doc *doc)
296	{
297	    size_t root = doc->root;
298	    if (!mcp_json_string_equals(doc, mcp_json_object_get(doc, root, "resultType"),
299	                                "complete")) return false;
300	    size_t fields[] = {
301	        mcp_json_object_get(doc, root, "taskId"),
302	        mcp_json_object_get(doc, root, "status"),
303	        mcp_json_object_get(doc, root, "createdAt"),
304	        mcp_json_object_get(doc, root, "lastUpdatedAt"),
305	        mcp_json_object_get(doc, root, "ttlMs"),
306	        mcp_json_object_get(doc, root, "result"),
307	        mcp_json_object_get(doc, root, "error")};
308	    for (size_t index = 0U; index < sizeof(fields) / sizeof(fields[0]); ++index)
309	        if (fields[index] != MCP_JSON_NO_TOKEN) return false;
310	    size_t meta = mcp_json_object_get(doc, root, "_meta");
311	    if (meta != MCP_JSON_NO_TOKEN && doc->tokens[meta].type != MCP_JSON_OBJECT)
312	        return false;
313	    for (size_t key = doc->tokens[root].first_child;
314	         key != MCP_JSON_NO_TOKEN;) {
315	        size_t value = doc->tokens[key].next_sibling;
316	        if (value == MCP_JSON_NO_TOKEN) return false;
317	        if (!mcp_json_string_equals(doc, key, "resultType") &&
318	            !mcp_json_string_equals(doc, key, "_meta")) return false;
319	        key = doc->tokens[value].next_sibling;
320	    }
321	    return true;
322	}
