324	bool mcp_protocol_async_validate_payload(const char *data, size_t length,
325	    mcp_protocol_async_payload_kind kind, bool *out_is_task)
326	{
327	    if (out_is_task != NULL) *out_is_task = false;
328	    if (data == NULL || length == 0U || length > MCP_JSON_MAX_BYTES) return false;
329	    mcp_json_doc doc = {0};
330	    if (!mcp_json_parse((const uint8_t *)data, length, &doc)) return false;
331	    bool okay = doc.tokens[doc.root].type == MCP_JSON_OBJECT;
332	    if (okay && kind == MCP_PROTOCOL_ASYNC_PAYLOAD_ERROR) {
333	        okay = validate_error(&doc, doc.root);
334	    } else if (okay && kind == MCP_PROTOCOL_ASYNC_PAYLOAD_TOOL_RESULT) {
335	        size_t result_type = mcp_json_object_get(&doc, doc.root, "resultType");
336	        if (result_type != MCP_JSON_NO_TOKEN &&
337	            mcp_json_string_equals(&doc, result_type, "task")) {
338	            okay = validate_create_task(&doc);
339	            if (okay && out_is_task != NULL) *out_is_task = true;
340	        } else {
341	            okay = validate_call_result(&doc, doc.root);
342	        }
343	    } else if (okay && kind == MCP_PROTOCOL_ASYNC_PAYLOAD_TASK_GET) {
344	        okay = mcp_json_string_equals(&doc,
345	            mcp_json_object_get(&doc, doc.root, "resultType"), "complete") &&
346	            validate_get_task(&doc);
347	    } else if (okay && kind == MCP_PROTOCOL_ASYNC_PAYLOAD_TASK_CANCEL) {
348	        okay = validate_cancel_ack(&doc);
349	    } else {
350	        okay = false;
351	    }
352	    mcp_json_doc_destroy(&doc);
353	    return okay;
354	}
