369	bool mcp_protocol_async_legacy_progress(const char *raw_token,
370	    size_t raw_token_length, uint32_t progress_permille,
371	    int64_t *prior_progress_permille, const char *message,
372	    mcp_json_buffer *out_notification)
373	{
374	    if (raw_token == NULL || raw_token_length == 0U ||
375	        raw_token_length > ASYNC_PROGRESS_TOKEN_LIMIT ||
376	        progress_permille > 1000U || prior_progress_permille == NULL ||
377	        (int64_t)progress_permille <= *prior_progress_permille ||
