381	static bool append_resource_read(mcp_protocol_session *session, const mcp_json_doc *doc,
382	                                 size_t params, size_t id,
383	                                 const mcp_protocol_backend *backend,
384	                                 mcp_json_buffer *out)
385	{
386	    size_t uri_token = mcp_json_object_get(doc, params, "uri");
387	    char uri[256];
388	    size_t length = 0U;
389	    if (!mcp_json_string_copy(doc, uri_token, uri, sizeof(uri) - 1U, &length))
390	        return append_error(out, (const char *)doc->source + doc->tokens[id].start,
391	            doc->tokens[id].end - doc->tokens[id].start, -32602, "resources/read requires a URI", NULL);
392	    uri[length] = '\0';
393	    mcp_json_buffer contents = {0};
394	    if (!mcp_json_buffer_init(&contents, 128U, MCP_RESPONSE_LIMIT)) return false;
395	    bool okay = backend != NULL && backend->read_resource != NULL &&
396	        backend->read_resource(backend->context, doc, uri, &contents);
397	    bool response_okay = okay ? append_response_prefix(out, doc, id) &&
398	        mcp_json_buffer_literal(out, "\"contents\":" ) &&
399	        mcp_json_buffer_append(out, contents.data, contents.length) &&
400	        append_response_suffix(out, session->modern) :
401	        append_error(out, (const char *)doc->source + doc->tokens[id].start,
402	            doc->tokens[id].end - doc->tokens[id].start, -32002, "resource not found", NULL);
403	    mcp_json_buffer_destroy(&contents);
404	    return response_okay;
405	}
