483	        bool emitted = has_id ? append_error(response,
484	            (const char *)doc.source + doc.tokens[id].start,
485	            doc.tokens[id].end - doc.tokens[id].start, -32000, "rate limit exceeded", NULL) : true;
486	        mcp_json_doc_destroy(&doc);
487	        return emitted;
488	    }
489	    size_t params = mcp_json_object_get(&doc, doc.root, "params");
490	    bool modern_probe = strcmp(method, "server/discover") == 0;
491	    bool modern_request = request_is_modern(&doc, params);
492	    if (modern_probe) {
493	        bool emitted = has_id ? (validate_modern_envelope(&doc, params) ?
494	            append_discover(session, &doc, id,
495	                mcp_protocol_async_tasks_ready(async_backend), response) : append_error(response,
496	                (const char *)doc.source + doc.tokens[id].start,
497	                doc.tokens[id].end - doc.tokens[id].start, -32022,
498	                "server/discover requires current protocol version metadata",
499	                "{\"supported\":[\"2026-07-28\"]}")) : true;
500	        mcp_json_doc_destroy(&doc);
501	        return emitted;
502	    }
503	    if (session->modern || modern_request) {
504	        if (!validate_modern_envelope(&doc, params)) {
505	            bool emitted = has_id ? append_error(response,
506	                (const char *)doc.source + doc.tokens[id].start,
507	                doc.tokens[id].end - doc.tokens[id].start, -32022,
508	                "unsupported or missing protocol version metadata",
509	                "{\"supported\":[\"2026-07-28\"]}") : true;
510	            mcp_json_doc_destroy(&doc);
511	            return emitted;
512	        }
513	        session->modern = true;
514	        memcpy(session->protocol_version, MCP_PROTOCOL_CURRENT, sizeof(MCP_PROTOCOL_CURRENT));
515	    } else if (strcmp(method, "initialize") != 0 &&
516	               strcmp(method, "notifications/initialized") != 0 &&
517	               !session->initialized && strcmp(method, "ping") != 0) {
518	        bool emitted = has_id ? append_error(response,
519	            (const char *)doc.source + doc.tokens[id].start,
520	            doc.tokens[id].end - doc.tokens[id].start, -32002,
521	            "initialize must complete before requests", NULL) : true;
522	        mcp_json_doc_destroy(&doc);
523	        return emitted;
524	    }
525	    bool okay = true;
526	    if (strcmp(method, "initialize") == 0) {
527	        okay = has_id ? append_initialize(session, &doc, params, id, response) : true;
528	    } else if (strcmp(method, "notifications/initialized") == 0 ||
529	               strcmp(method, "notifications/cancelled") == 0 ||
530	               strcmp(method, "notifications/progress") == 0) {
531	        if (strcmp(method, "notifications/initialized") == 0) session->initialized = true;
532	        else if (strcmp(method, "notifications/cancelled") == 0 &&
533	                 !has_id && session->initialized && !session->modern &&
534	                 async_backend != NULL && async_backend->cancel_request != NULL &&
535	                 params != MCP_JSON_NO_TOKEN &&
536	                 doc.tokens[params].type == MCP_JSON_OBJECT) {
537	            size_t request_id = mcp_json_object_get(&doc, params, "requestId");
538	            if (request_id != MCP_JSON_NO_TOKEN &&
539	                (doc.tokens[request_id].type == MCP_JSON_STRING ||
540	                 doc.tokens[request_id].type == MCP_JSON_NUMBER))
541	                async_backend->cancel_request(async_backend->context, &doc,
542	                                               request_id);
543	        }
544	    } else if (strcmp(method, "ping") == 0) {
545	        okay = !has_id || (append_response_prefix(response, &doc, id) &&
546	            append_response_suffix(response, session->modern));
547	    } else if (strcmp(method, "tools/list") == 0) {
548	        okay = !has_id || (append_response_prefix(response, &doc, id) &&
549	            mcp_json_buffer_literal(response, "\"tools\":" ) &&
550	            mcp_tools_list_json(response) && append_response_suffix(response, session->modern));
551	    } else if (strcmp(method, "tools/call") == 0) {
552	        okay = !has_id || append_tool_call(session, &doc, params, id, backend,
553	                                            async_backend, response);
554	    } else if (strcmp(method, "tasks/get") == 0 ||
555	               strcmp(method, "tasks/cancel") == 0) {
556	        okay = !has_id || append_task_method(session, &doc, params, id, method,
557	                                              async_backend, response);
558	    } else if (strcmp(method, "resources/list") == 0) {
559	        okay = !has_id || (append_response_prefix(response, &doc, id) &&
560	            append_resources_list(response) && append_response_suffix(response, session->modern));
561	    } else if (strcmp(method, "resources/read") == 0) {
562	        okay = !has_id || append_resource_read(session, &doc, params, id, backend, response);
563	    } else if (strcmp(method, "prompts/list") == 0) {
564	        okay = !has_id || (append_response_prefix(response, &doc, id) &&
565	            append_prompts_list(response) && append_response_suffix(response, session->modern));
566	    } else if (strcmp(method, "prompts/get") == 0) {
567	        okay = !has_id || (append_response_prefix(response, &doc, id) &&
568	            (append_prompt_get(&doc, params, response) ||
569	             mcp_json_buffer_literal(response, "\"messages\":[]" )) &&
570	            append_response_suffix(response, session->modern));
571	    } else if (has_id) {
572	        okay = append_error(response, (const char *)doc.source + doc.tokens[id].start,
573	            doc.tokens[id].end - doc.tokens[id].start, -32601, "method not found", NULL);
574	    }
575	    mcp_json_doc_destroy(&doc);
576	    return okay;
577	}
