595	    size_t method = mcp_json_object_get(&doc, doc.root, "method");
596	    bool expects = mcp_json_object_get(&doc, doc.root, "id") != MCP_JSON_NO_TOKEN;
597	    if (mcp_json_string_equals(&doc, method, "notifications/initialized") ||
598	        mcp_json_string_equals(&doc, method, "notifications/cancelled") ||
599	        mcp_json_string_equals(&doc, method, "notifications/progress")) expects = false;
600	    if (!expects && !mcp_json_string_equals(&doc, method, "notifications/initialized") &&
601	        !mcp_json_string_equals(&doc, method, "notifications/cancelled") &&
602	        !mcp_json_string_equals(&doc, method, "notifications/progress")) expects = true;
603	    mcp_json_doc_destroy(&doc);
604	    return expects;
