 18	static bool string_field(const mcp_json_doc *doc, size_t object,
 19	                         const char *key, char *buffer, size_t capacity,
 20	                         size_t *out_length)
 21	{
 22	    size_t token = mcp_json_object_get(doc, object, key);
 23	    if (!mcp_json_string_copy(doc, token, buffer, capacity, out_length)) return false;
 24	    return memchr(buffer, '\0', *out_length) == NULL;
 25	}
 26	
 27	static bool valid_string_token(const mcp_json_doc *doc, size_t token,
 28	                               bool require_nonempty)
 29	{
 30	    if (token == MCP_JSON_NO_TOKEN || doc->tokens[token].type != MCP_JSON_STRING)
 31	        return false;
 32	    size_t start = doc->tokens[token].start + 1U;
 33	    size_t end = doc->tokens[token].end - 1U;
 34	    if (require_nonempty && start == end) return false;
 35	    for (size_t cursor = start; cursor < end;) {
 36	        if (doc->source[cursor] != '\\') { cursor++; continue; }
 37	        if (cursor + 1U >= end) return false;
 38	        if (doc->source[cursor + 1U] != 'u') { cursor += 2U; continue; }
 39	        if (end - cursor < 6U) return false;
 40	        unsigned codepoint = 0U;
 41	        for (size_t index = cursor + 2U; index < cursor + 6U; ++index) {
 42	            uint8_t ch = doc->source[index];
 43	            unsigned digit = ch >= '0' && ch <= '9' ? (unsigned)(ch - '0') :
 44	                ch >= 'a' && ch <= 'f' ? (unsigned)(ch - 'a') + 10U :
 45	                ch >= 'A' && ch <= 'F' ? (unsigned)(ch - 'A') + 10U : 16U;
 46	            if (digit > 15U) return false;
 47	            codepoint = (codepoint << 4U) | digit;
 48	        }
 49	        if (codepoint == 0U) return false;
 50	        cursor += 6U;
 51	    }
 52	    return true;
 53	}
 54	
 55	static bool optional_string_field(const mcp_json_doc *doc, size_t object,
 56	                                  const char *key, bool require_nonempty)
 57	{
 58	    size_t token = mcp_json_object_get(doc, object, key);
 59	    return token == MCP_JSON_NO_TOKEN ||
 60	        valid_string_token(doc, token, require_nonempty);
 61	}
