 63	bool mcp_protocol_async_task_id(const mcp_json_doc *doc, size_t params,
 64	                                char *out_id, size_t capacity)
 65	{
 66	    if (doc == NULL || params == MCP_JSON_NO_TOKEN || out_id == NULL ||
 67	        capacity < 2U) return false;
 68	    size_t length = 0U;
 69	    if (!string_field(doc, params, "taskId", out_id, capacity - 1U, &length) ||
 70	        length == 0U || length > ASYNC_TASK_ID_LIMIT) return false;
 71	    out_id[length] = '\0';
 72	    return true;
 73	}
