149	static bool validate_resource_block(const mcp_json_doc *doc, size_t block)
150	{
151	    size_t resource = mcp_json_object_get(doc, block, "resource");
152	    if (resource == MCP_JSON_NO_TOKEN ||
153	        doc->tokens[resource].type != MCP_JSON_OBJECT ||
154	        !optional_string_field(doc, resource, "uri", true) ||
155	        !optional_string_field(doc, resource, "mimeType", true)) return false;
156	    size_t uri = mcp_json_object_get(doc, resource, "uri");
157	    size_t text = mcp_json_object_get(doc, resource, "text");
158	    size_t blob = mcp_json_object_get(doc, resource, "blob");
159	    if (!valid_string_token(doc, uri, true) ||
160	        ((text == MCP_JSON_NO_TOKEN) == (blob == MCP_JSON_NO_TOKEN)) ||
161	        (text != MCP_JSON_NO_TOKEN && !valid_string_token(doc, text, false)) ||
162	        (blob != MCP_JSON_NO_TOKEN && !valid_string_token(doc, blob, false)))
163	        return false;
164	    return validate_annotations(doc, block);
165	}
