167	static bool validate_resource_link(const mcp_json_doc *doc, size_t block)
168	{
169	    size_t uri = mcp_json_object_get(doc, block, "uri");
170	    size_t name = mcp_json_object_get(doc, block, "name");
171	    size_t icons = mcp_json_object_get(doc, block, "icons");
172	    size_t size = mcp_json_object_get(doc, block, "size");
173	    uint64_t ignored_size = 0U;
174	    return valid_string_token(doc, uri, true) &&
175	        valid_string_token(doc, name, true) &&
176	        optional_string_field(doc, block, "title", false) &&
177	        optional_string_field(doc, block, "description", false) &&
178	        optional_string_field(doc, block, "mimeType", true) &&
179	        (icons == MCP_JSON_NO_TOKEN || doc->tokens[icons].type == MCP_JSON_ARRAY) &&
180	        (size == MCP_JSON_NO_TOKEN ||
181	         mcp_json_uint(doc, size, &ignored_size)) &&
182	        validate_annotations(doc, block);
183	}
