185	static bool validate_content_block(const mcp_json_doc *doc, size_t block)
186	{
187	    if (doc->tokens[block].type != MCP_JSON_OBJECT ||
188	        !validate_annotations(doc, block)) return false;
189	    size_t type = mcp_json_object_get(doc, block, "type");
190	    if (!valid_string_token(doc, type, true)) return false;
191	    if (mcp_json_string_equals(doc, type, "text")) {
192	        size_t text = mcp_json_object_get(doc, block, "text");
193	        return valid_string_token(doc, text, false);
194	    }
195	    if (mcp_json_string_equals(doc, type, "image") ||
196	        mcp_json_string_equals(doc, type, "audio")) {
197	        return valid_string_token(doc, mcp_json_object_get(doc, block, "data"), true) &&
198	            valid_string_token(doc, mcp_json_object_get(doc, block, "mimeType"), true);
199	    }
200	    if (mcp_json_string_equals(doc, type, "resource"))
201	        return validate_resource_block(doc, block);
202	    if (mcp_json_string_equals(doc, type, "resource_link"))
203	        return validate_resource_link(doc, block);
204	    return false;
205	}
