207	static bool validate_content(const mcp_json_doc *doc, size_t token)
208	{
209	    if (token == MCP_JSON_NO_TOKEN || doc->tokens[token].type != MCP_JSON_ARRAY)
210	        return false;
211	    for (size_t block = doc->tokens[token].first_child;
212	         block != MCP_JSON_NO_TOKEN; block = doc->tokens[block].next_sibling)
213	        if (!validate_content_block(doc, block)) return false;
214	    return true;
215	}
