217	static bool validate_call_result(const mcp_json_doc *doc, size_t object)
218	{
219	    if (object == MCP_JSON_NO_TOKEN || doc->tokens[object].type != MCP_JSON_OBJECT)
220	        return false;
221	    size_t content = mcp_json_object_get(doc, object, "content");
222	    size_t is_error = mcp_json_object_get(doc, object, "isError");
223	    size_t structured = mcp_json_object_get(doc, object, "structuredContent");
224	    size_t kind = mcp_json_object_get(doc, object, "resultType");
225	    size_t meta = mcp_json_object_get(doc, object, "_meta");
226	    return validate_content(doc, content) &&
227	        (is_error == MCP_JSON_NO_TOKEN || doc->tokens[is_error].type == MCP_JSON_TRUE ||
228	         doc->tokens[is_error].type == MCP_JSON_FALSE) &&
229	        (structured == MCP_JSON_NO_TOKEN ||
230	         doc->tokens[structured].type == MCP_JSON_OBJECT) &&
231	        (kind == MCP_JSON_NO_TOKEN || mcp_json_string_equals(doc, kind, "complete")) &&
232	        (meta == MCP_JSON_NO_TOKEN || doc->tokens[meta].type == MCP_JSON_OBJECT);
233	}
