277	        return result == MCP_JSON_NO_TOKEN && error != MCP_JSON_NO_TOKEN &&
278	            validate_error(doc, error);
279	    return result == MCP_JSON_NO_TOKEN && error == MCP_JSON_NO_TOKEN;
280	}
