 50	pub enum ToolValidationError { UnknownTool, UnexpectedArgument, WrongType, MissingRequired, InvalidLoopMode, InvalidTemplateAttributes, InvalidTransactionLength, InvalidArguments }
 51	
 52	pub fn tool_schemas() -> Result<Vec<u8>, ProtocolError> {
 53	    let mut out = JsonBuffer::new(4096, MAX_BYTES).map_err(ProtocolError::Buffer)?;
 54	    out.literal("[").map_err(ProtocolError::Buffer)?;
 55	    for (index, tool) in TOOLS.iter().enumerate() {
 56	        if index != 0 { out.literal(",").map_err(ProtocolError::Buffer)?; }
 57	        out.literal("{\"name\":").map_err(ProtocolError::Buffer)?;
 58	        append_string(&mut out, tool.name.as_bytes())?;
 59	        out.literal(",\"description\":").map_err(ProtocolError::Buffer)?;
 60	        append_string(&mut out, tool.description.as_bytes())?;
 61	        out.literal(",\"inputSchema\":{\"type\":\"object\",\"properties\":").map_err(ProtocolError::Buffer)?;
 62	        out.literal(tool.properties).map_err(ProtocolError::Buffer)?;
 63	        out.literal(",\"required\":").map_err(ProtocolError::Buffer)?;
 64	        out.literal("[").map_err(ProtocolError::Buffer)?;
 65	        for (required_index, field) in tool.required.split(',').filter(|s| !s.is_empty()).enumerate() {
 66	            if required_index != 0 { out.literal(",").map_err(ProtocolError::Buffer)?; }
 67	            append_string(&mut out, field.as_bytes())?;
 68	        }
 69	        out.literal("],\"additionalProperties\":false}}").map_err(ProtocolError::Buffer)?;
 70	    }
 71	    out.literal("]").map_err(ProtocolError::Buffer)?;
 72	    let mut bytes = Vec::new();
 73	    bytes.try_reserve_exact(out.len()).map_err(|_| ProtocolError::Allocation)?;
 74	    bytes.extend_from_slice(out.as_bytes());
 75	    Ok(bytes)
 76	}
