128	static bool append_csv_array(mcp_json_buffer *out, const char *csv)
129	{
130	    if (!mcp_json_buffer_literal(out, "[")) return false;
131	    bool first = true;
132	    const char *cursor = csv;
133	    while (*cursor != '\0') {
134	        const char *end = strchr(cursor, ',');
135	        size_t length = end == NULL ? strlen(cursor) : (size_t)(end - cursor);
136	        if (!first && !mcp_json_buffer_literal(out, ",")) return false;
137	        if (!mcp_json_buffer_quoted(out, cursor, length)) return false;
138	        first = false;
139	        if (end == NULL) break;
140	        cursor = end + 1;
141	    }
142	    return mcp_json_buffer_literal(out, "]");
143	}
