145	bool mcp_tools_list_json(mcp_json_buffer *out)
146	{
147	    if (out == NULL || !mcp_json_buffer_literal(out, "[")) return false;
148	    for (size_t index = 0U; index < sizeof(tools) / sizeof(tools[0]); index++) {
149	        const mcp_tool_schema *tool = &tools[index];
150	        if (index > 0U && !mcp_json_buffer_literal(out, ",")) return false;
151	        if (!mcp_json_buffer_literal(out, "{\"name\":" ) ||
152	            !mcp_json_buffer_quoted(out, tool->name, strlen(tool->name)) ||
153	            !mcp_json_buffer_literal(out, ",\"description\":" ) ||
154	            !mcp_json_buffer_quoted(out, tool->description, strlen(tool->description)) ||
155	            !mcp_json_buffer_literal(out, ",\"inputSchema\":{\"type\":\"object\",\"properties\":" ) ||
156	            !mcp_json_buffer_literal(out, tool->properties) ||
157	            !mcp_json_buffer_literal(out, ",\"required\":" ) ||
158	            !append_csv_array(out, tool->required) ||
159	            !mcp_json_buffer_literal(out, ",\"additionalProperties\":false}}")) return false;
160	    }
161	    return mcp_json_buffer_literal(out, "]");
162	}
