171	static const char *field_type(const char *fields, const char *key)
172	{
173	    size_t key_length = strlen(key);
174	    const char *cursor = fields;
175	    while (*cursor != '\0') {
176	        const char *colon = strchr(cursor, ':');
177	        if (colon == NULL) return NULL;
178	        const char *end = strchr(colon + 1, ';');
179	        size_t name_length = (size_t)(colon - cursor);
180	        if (name_length == key_length && memcmp(cursor, key, key_length) == 0) return colon + 1;
181	        if (end == NULL) return NULL;
182	        cursor = end + 1;
183	    }
184	    return NULL;
185	}
