187	static bool type_is_one(const mcp_json_doc *doc, size_t token, const char *type)
188	{
189	    if (token >= doc->token_count) return false;
190	    mcp_json_type actual = doc->tokens[token].type;
191	    if (strcmp(type, "string") == 0) return actual == MCP_JSON_STRING;
192	    if (strcmp(type, "object") == 0) return actual == MCP_JSON_OBJECT;
193	    if (strcmp(type, "array") == 0) return actual == MCP_JSON_ARRAY;
