203	static bool type_is(const mcp_json_doc *doc, size_t token, const char *types)
204	{
205	    const char *cursor = types;
206	    while (*cursor != '\0') {
207	        const char *end = strchr(cursor, '|');
208	        size_t length = end == NULL ? strlen(cursor) : (size_t)(end - cursor);
209	        char type[24];
210	        if (length == 0U || length >= sizeof(type)) return false;
211	        memcpy(type, cursor, length);
212	        type[length] = '\0';
213	        if (type_is_one(doc, token, type)) return true;
214	        if (end == NULL) break;
215	        cursor = end + 1;
216	    }
217	    return false;
218	}
